package ca.teamdman.sfm.gametest.tests.cable.tunnelled;

import ca.teamdman.sfm.common.capability.SFMBlockCapabilityDiscovery;
import ca.teamdman.sfm.common.capability.SFMWellKnownCapabilities;
import ca.teamdman.sfm.common.registry.registration.SFMBlocks;
import ca.teamdman.sfm.gametest.SFMGameTestDefinition;
import ca.teamdman.sfm.gametest.SFMGameTestGenerator;
import ca.teamdman.sfm.gametest.SFMGameTestGeneratorBase;
import ca.teamdman.sfm.gametest.SFMGameTestHelper;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.entity.FurnaceBlockEntity;
import net.neoforged.neoforge.items.IItemHandler;

import java.util.List;
import java.util.Locale;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.function.Consumer;
import java.util.function.Supplier;

/**
 * Tests the original tunnel forwarding contract independently of cache relay recovery.
 * A furnace distinguishes its top input, bottom output and horizontal fuel faces;
 * an opposite-side decoy catches querying the near block instead of the far block.
 */
@SFMGameTestGenerator
public class TunnelledCapabilityForwardingGameTestGenerator extends SFMGameTestGeneratorBase {
    private static final BlockPos TUNNEL = new BlockPos(3, 2, 3);

    private record Variant(String name, Supplier<Block> block) {}

    private static final List<Variant> VARIANTS = List.of(
            new Variant("tunnelled_manager", SFMBlocks.TUNNELLED_MANAGER::get),
            new Variant("tunnelled_cable", SFMBlocks.TUNNELLED_CABLE::get),
            new Variant("tunnelled_cable_facade", SFMBlocks.TUNNELLED_CABLE_FACADE::get),
            new Variant("tunnelled_fancy_cable", SFMBlocks.TUNNELLED_FANCY_CABLE::get),
            new Variant("tunnelled_fancy_cable_facade", SFMBlocks.TUNNELLED_FANCY_CABLE_FACADE::get)
    );

    @Override
    public void generateTests(Consumer<SFMGameTestDefinition> tests) {
        for (Variant variant : VARIANTS) {
            for (Direction face : Direction.values()) {
                tests.accept(new ForwardingTest(variant, face));
            }
            tests.accept(new NullSideTest(variant));
        }
    }

    private static void placeTunnel(SFMGameTestHelper helper, Variant variant) {
        helper.setBlock(TUNNEL, variant.block.get());
        if (variant.name.contains("facade")) {
            helper.setFacade(TUNNEL, Blocks.GLOWSTONE.defaultBlockState());
        }
    }

    private static String describeFace(IItemHandler handler) {
        StringBuilder result = new StringBuilder().append(handler.getSlots());
        for (int slot = 0; slot < handler.getSlots(); slot++) {
            ItemStack stack = handler.getStackInSlot(slot);
            result.append('|').append(stack.getItem()).append(':').append(stack.getCount());
            result.append('/').append(handler.extractItem(slot, 1, true).getCount());
            result.append('/').append(handler.insertItem(slot, new ItemStack(Items.IRON_ORE), true).getCount());
            result.append('/').append(handler.insertItem(slot, new ItemStack(Items.COAL), true).getCount());
        }
        return result.toString();
    }

    private static final class ForwardingTest extends SFMGameTestDefinition {
        private final Variant variant;
        private final Direction face;

        private ForwardingTest(Variant variant, Direction face) {
            this.variant = variant;
            this.face = face;
        }

        @Override
        public String template() {
            return "7x4x7";
        }

        @Override
        public String testName() {
            return variant.name + "_forwarding_contract_" + face.name().toLowerCase(Locale.ROOT);
        }

        @Override
        public int maxTicks() {
            return 15;
        }

        @Override
        public void run(SFMGameTestHelper helper) {
            BlockPos far = TUNNEL.relative(face.getOpposite());
            BlockPos near = TUNNEL.relative(face);
            placeTunnel(helper, variant);
            helper.setBlock(far, Blocks.FURNACE);
            helper.setBlock(near, SFMBlocks.TEST_BARREL.get());
            FurnaceBlockEntity furnace = helper.getBlockEntity(far, FurnaceBlockEntity.class);
            furnace.setItem(0, new ItemStack(Items.IRON_ORE, 11));
            furnace.setItem(1, new ItemStack(Items.COAL, 7));
            furnace.setItem(2, new ItemStack(Items.IRON_INGOT, 3));
            var direct = helper.getItemHandler(far, face);
            var forwarded = helper.getItemHandler(TUNNEL, face);
            if (face == Direction.UP || face == Direction.DOWN) {
                helper.assertTrue(!describeFace(direct).equals(describeFace(helper.getItemHandler(far, face.getOpposite()))),
                        "Furnace fixture did not distinguish its top and bottom faces");
            }
            helper.assertTrue(forwarded.getSlots() == direct.getSlots(),
                    "Tunnel queried its near-side barrel or changed the furnace side");
            helper.assertTrue(describeFace(forwarded).equals(describeFace(direct)),
                    "Tunnel changed far position, forwarded face or item insertion/extraction behavior, face=" + face);
            helper.assertTrue(!SFMBlockCapabilityDiscovery.discoverCapabilityFromLevel(
                            helper.getLevel(), SFMWellKnownCapabilities.ENERGY,
                            helper.absolutePos(TUNNEL), face).isPresent(),
                    "An item-only endpoint must not manufacture an energy capability");
            // Legacy tunnels return the endpoint's LazyOptional. Its invalidation
            // must survive forwarding; this does not claim a position-cache relay.
            var retained = helper.getBlockEntity(TUNNEL).getCapability(
                    SFMWellKnownCapabilities.ITEM_HANDLER.capabilityKind(), face);
            helper.assertTrue(retained.isPresent(), "No legacy forwarded LazyOptional");
            AtomicInteger invalidations = new AtomicInteger();
            retained.addListener(ignored -> invalidations.incrementAndGet());
            helper.runAfterDelay(5, () -> {
                helper.setBlock(far, Blocks.AIR);
                helper.assertTrue(!retained.isPresent(), "Removed endpoint left a valid forwarded LazyOptional");
                helper.assertTrue(invalidations.get() == 1,
                        "Forwarded endpoint must invalidate once, got " + invalidations.get());
                helper.succeed();
            });
        }
    }

    private static final class NullSideTest extends SFMGameTestDefinition {
        private final Variant variant;

        private NullSideTest(Variant variant) {
            this.variant = variant;
        }

        @Override
        public String template() {
            return "7x4x7";
        }

        @Override
        public String testName() {
            return variant.name + "_forwarding_null_side_contract";
        }

        @Override
        public void run(SFMGameTestHelper helper) {
            placeTunnel(helper, variant);
            for (Direction direction : Direction.values()) {
                helper.setBlock(TUNNEL.relative(direction), SFMBlocks.TEST_BARREL.get());
            }
            var result = SFMBlockCapabilityDiscovery.discoverCapabilityFromLevel(
                    helper.getLevel(), SFMWellKnownCapabilities.ITEM_HANDLER,
                    helper.absolutePos(TUNNEL), null);
            if (variant.name.equals("tunnelled_manager")) {
                helper.assertTrue(result.isPresent(), "Legacy manager null side must retain its own disk slot");
                helper.assertTrue(helper.getItemHandler(TUNNEL, null).getSlots() == 1,
                        "Legacy manager null side forwarded to an adjacent barrel instead of its disk slot");
            } else {
                helper.assertTrue(!result.isPresent(), "A null tunnel side must not choose an adjacent barrel");
            }
            helper.succeed();
        }
    }
}
